<template><el-card shadow="never"><template #header><div class="head"><div><b>项目用例</b><p>当前项目可复用、可评审的测试资产。</p></div><div><el-button @click="$router.push(`/case-library?project_id=${projectId}`)">完整用例库</el-button><el-button type="primary" @click="$router.push(`/case-generation?project_id=${projectId}`)">生成用例</el-button></div></div></template><el-table v-loading="loading" :data="items"><el-table-column prop="title" label="用例名称" min-width="240"/><el-table-column prop="execution_kind" label="执行类型" width="100"/><el-table-column prop="priority" label="优先级" width="90"/><el-table-column label="评审状态" width="110"><template #default="{row}"><el-tag effect="light">{{ reviewLabel(row.review_state) }}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/case-assert/${row.id}`)">配置断言</el-button><el-button link @click="$router.push(`/case-library?project_id=${projectId}&case_id=${row.id}`)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="项目还没有用例，可先从需求或接口文档生成"/></el-card></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{caseApi}from'@/api';const projectId=String(useRoute().params.id),loading=ref(false),items=ref<any[]>([]);function reviewLabel(v:string){return({draft:'草稿',pending:'待评审',approved:'已通过',changes_requested:'需修改'}as any)[v]||v}onMounted(async()=>{loading.value=true;try{const r:any=await caseApi.list({project_id:projectId,page:1,page_size:50});items.value=r?.data?.items||[]}finally{loading.value=false}})</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:flex-start}.head p{margin:5px 0 0;color:var(--app-text-secondary);font-size:13px}@media(max-width:768px){.head{gap:12px;flex-direction:column}}</style>
